import { zRenderable } from "../Renderable.mjs";
import { z } from "zod";
// valid route template segments
const templateSegmentRE = /^:?[a-zA-Z0-9_-]+$/;
const segmentRE = /^[a-zA-Z0-9_-]+$/;
// zRouteTemplate
// start with /
// segments are a-z0-9 or :a-z
// can optionally end with *
export const zRouteTemplate = z
    .string()
    .trim()
    .superRefine((route, ctx) => {
    // special case for /
    if (route === "/")
        return true;
    if (route.length === 0) {
        ctx.addIssue({
            code: z.ZodIssueCode.custom,
            message: "Empty route",
        });
        return false;
    }
    if (route.startsWith("/")) {
        route = route.replace("/", "");
    }
    else {
        ctx.addIssue({
            code: z.ZodIssueCode.custom,
            message: `Routes must start with "/"`,
        });
        return false;
    }
    const segments = route.split("/");
    return segments.every((part, index) => {
        if (part === "*") {
            if (index !== segments.length - 1) {
                ctx.addIssue({
                    code: z.ZodIssueCode.custom,
                    message: `"*" must be last route segment in "${route}"`,
                });
                return false;
            }
            return true;
        }
        if (templateSegmentRE.test(part))
            return true;
        ctx.addIssue({
            code: z.ZodIssueCode.custom,
            message: `Invalid route segment "${part}" in "${route}". [a-zA-Z0-9_]+`,
        });
        return false;
    });
});
export const zRouteMap = z.record(zRouteTemplate, z.function().args(z.unknown(), z.record(z.string())));
// similar to route template but these
// don't have to start with
// nor comtain wild cards
const zLinkTemplate = z
    .string()
    .trim()
    .superRefine((route, ctx) => {
    if (route === "/")
        return true;
    if (route.length === 0) {
        ctx.addIssue({
            code: z.ZodIssueCode.custom,
            message: "Empty path",
        });
        return false;
    }
    if (!route.startsWith("/")) {
        ctx.addIssue({
            code: z.ZodIssueCode.custom,
            message: "Navigation path should start with /",
        });
        return false;
    }
    return route
        .split("/")
        .slice(1)
        .every((part) => {
        if (templateSegmentRE.test(part))
            return true;
        ctx.addIssue({
            code: z.ZodIssueCode.custom,
            message: `Invalid segment "${part}" in "${route}"`,
        });
        return false;
    });
});
export const zAction = z
    .string()
    .trim()
    .superRefine((link, ctx) => {
    // nav -> validate
    if (link.startsWith("nav:")) {
        return validateSegments(link, ctx);
    }
    if (link.length === 0) {
        ctx.addIssue({
            code: z.ZodIssueCode.custom,
            message: "Empty action",
        });
        return false;
    }
    return true;
});
// zLink
// optionally starts with nav:
// length > 0 (excluding the nav:)
// each segment is a valid url segment
export const zLink = z.string().trim().superRefine(validateSegments);
function validateSegments(link, ctx) {
    // explcitly allow links to start with nav:
    if (link.startsWith("nav:")) {
        link = link.replace("nav:", "");
    }
    if (link === "/")
        return true;
    if (link.length === 0) {
        ctx.addIssue({
            code: z.ZodIssueCode.custom,
            message: "Empty route",
        });
        return false;
    }
    if (link.startsWith("/")) {
        link = link.replace("/", "");
    }
    return link.split("/").every((part) => {
        // TODO: is this the right test?
        if (/^[0-9a-zA-Z-_.!~*'()%]*$/.test(part)) {
            return true;
        }
        else {
            ctx.addIssue({
                code: z.ZodIssueCode.custom,
                message: `Invalid route segment "${part}" in "${link}"`,
            });
            return false;
        }
    });
}
// zNavTemplate
// route: segments are a-z or :a-z
// params: object with key / number or string
// all slots must be filled with strong or number
export const zNavTemplate = z
    .object({
    route: zLinkTemplate,
    params: z.object({}).passthrough(),
})
    .superRefine(({ route, params }, ctx) => route.split("/").every((part) => {
    if (!part.startsWith(":"))
        return true;
    // @ts-ignore
    const value = params[part.slice(1)];
    const type = typeof value;
    switch (type) {
        case "string":
        case "number":
            return true;
        case "undefined":
            ctx.addIssue({
                code: z.ZodIssueCode.custom,
                message: `Missing param for "${part}" in "${route}"`,
            });
            return false;
        default:
            ctx.addIssue({
                code: z.ZodIssueCode.custom,
                message: `Param values must be string or number but got "${type}:${value}" for "${part}" in "${route}"`,
            });
            return false;
    }
}))
    .transform(({ route, params }, ctx) => route
    .split("/")
    .map((part) => 
// @ts-ignore
part.startsWith(":") ? encodeURIComponent(params[part.slice(1)]) : part)
    .join("/"));
export const zRoute = zLink.or(zNavTemplate);
const zOption = z
    .object({
    label: zRenderable.optional(),
    icon: z.string().optional(),
    disabled: z.boolean().optional(),
    indent: z.number().optional(),
    nav: zRoute,
})
    .refine(({ label, icon }) => label || icon, "label and/or icon need to be set");
export const zOptions = z.array(zOption).min(1);
// TODO: readOnly
const zNavBarProps = z.object({
    options: zOptions,
    appearance: z.enum(["nav", "tabs"]).default("nav").optional(),
});
export function NavBar(define) {
    return define("NavBar")
        .props(zNavBarProps)
        .render((props) => ({
        id: props.id,
        options: props.options,
        appearance: props.appearance,
    }));
}
